+                "SELECT id FROM users WHERE email = ?", Long.class, email);
+    }
+
+    /** 같은 본문은 같은 동일 버전 키를 만든다. 컨테이너를 공유하므로 시작 금액으로 흔든다. */
+    private String uniqueBody() throws Exception {
